func (h *TransmuteHandler) binarySearchSplit(ctx context.Context, masterTable string, batch []NatsMsgTask, causeErr ...error) {
	var rootErr error
	if len(causeErr) > 0 {
		rootErr = causeErr[0]
	}
	if len(batch) == 1 {
		task := batch[0]
		// Nếu 1 NATS message chứa nhiều Events hoặc nhiều SourceIDs, tiếp tục chia đôi
		// mảng Events / SourceIDs để cô lập chính xác 1 bản ghi Poison Pill duy nhất,
		// cứu toàn bộ các bản ghi hợp lệ đi cùng trong message đó.
		if len(task.Req.Events) > 1 || (len(task.Req.Events) == 0 && len(task.Req.SourceIDs) > 1) {
			h.splitSingleTaskPayload(ctx, masterTable, task, rootErr)
			return
		}

